import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './HomePage.css';

function HomePage({ user }) {
  const [userEmail, setUserEmail] = useState('');
  const [availableSlots, setAvailableSlots] = useState([]);
  const [selectedSlotId, setSelectedSlotId] = useState('');
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [hourlyRate, setHourlyRate] = useState(0);
  const [totalCost, setTotalCost] = useState(0);
  const [message, setMessage] = useState('');

  const navigate = useNavigate();

  // Check login & set email
  useEffect(() => {
    const storedEmail = localStorage.getItem('userEmail');
    if (user?.email) {
      setUserEmail(user.email);
    } else if (storedEmail) {
      setUserEmail(storedEmail);
    } else {
      navigate('/');
    }
  }, [user, navigate]);

  // Fetch available slots
  useEffect(() => {
    fetch('http://localhost:8081/api/slots/available')
      .then((res) => res.json())
      .then((data) => setAvailableSlots(data))
      .catch((err) => console.error('Error fetching slots:', err));
  }, []);

  // Update hourly rate when slot changes
  useEffect(() => {
    const slot = availableSlots.find((s) => s.id === Number(selectedSlotId));
    if (slot) {
      setHourlyRate(slot.hourlyRate);
    }
  }, [selectedSlotId, availableSlots]);

  // Calculate total cost
  useEffect(() => {
    if (startTime && endTime && hourlyRate) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffHours = Math.abs(end - start) / 36e5; // milliseconds to hours
      setTotalCost((diffHours * hourlyRate).toFixed(2));
    } else {
      setTotalCost(0);
    }
  }, [startTime, endTime, hourlyRate]);

  // Handle booking
  const handleBooking = () => {
    if (!selectedSlotId || !vehicleNumber || !startTime || !endTime) {
      setMessage('Please fill in all details before booking.');
      return;
    }

    const bookingData = {
      userId: 1, // Replace with actual logged-in user ID from backend
      parkingSlotId: Number(selectedSlotId),
      vehicleNumber,
      startTime,
      endTime
    };

    fetch('http://localhost:8081/api/bookings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bookingData)
    })
      .then(async (res) => {
        if (res.ok) {
          const data = await res.json();
          setMessage(`Booking Confirmed! Total Cost: $${data.totalCost}`);
          // Refresh slots after booking
          fetch('http://localhost:8081/api/slots/available')
            .then((r) => r.json())
            .then((d) => setAvailableSlots(d));
        } else {
          const errorText = await res.text();
          setMessage(`Error: ${errorText}`);
        }
      })
      .catch((err) => {
        console.error('Error creating booking:', err);
        setMessage('An error occurred. Please try again.');
      });
  };

  const handleLogout = () => {
    localStorage.removeItem('userEmail');
    navigate('/');
  };

  return (
    <div className="home-container">
      <h1>Parking Slot Booking System</h1>
      {userEmail && <h3>Logged in as: {userEmail}</h3>}
      <button onClick={handleLogout} className="logout-button">Logout</button>

      <h2>Available Slots</h2>
      <select value={selectedSlotId} onChange={(e) => setSelectedSlotId(e.target.value)}>
        <option value="">-- Select a slot --</option>
        {availableSlots.map((slot) => (
          <option key={slot.id} value={slot.id}>
            {slot.slotNumber} ({slot.slotType}) - ${slot.hourlyRate}/hr
          </option>
        ))}
      </select>

      <div className="booking-form">
        <input
          type="text"
          placeholder="Vehicle Number"
          value={vehicleNumber}
          onChange={(e) => setVehicleNumber(e.target.value)}
        />
        <label>Start Time:</label>
        <input
          type="datetime-local"
          value={startTime}
          onChange={(e) => setStartTime(e.target.value)}
        />
        <label>End Time:</label>
        <input
          type="datetime-local"
          value={endTime}
          onChange={(e) => setEndTime(e.target.value)}
        />
        <p>Total Cost: ${totalCost}</p>
        <button onClick={handleBooking} className="book-button">Book Slot</button>
      </div>

      {message && <p className="message">{message}</p>}
    </div>
  );
}

export default HomePage;
